async function getRayons(req, res) {
  const rayons = await db.collection('rayons').find().toArray();
  res.json(rayons);
}

async function getProducts(req, res) {
  const products = await db.collection('articles').find().toArray();
  res.json(products);
}

async function getArticlesByRayon(req, res) {
  const { id } = req.params;
  const articles = await db.collection('articles').find({ rayonId: id }).toArray();
  res.json(articles);
}

function addToCart(product) {
  var existing = cart().find(function (item) {
    return item.id === product.id;
  });

  if (existing) {
    cart.update(function (items) {
      return items.map(function (item) {
        if (item.id === product.id) {
          return { ...item, qty: item.qty + 1 };
        }

        return item;
      });
    });
    return;
  }

  cart.update(function (items) {
    return [...items, { ...product, qty: 1 }];
  });
}

function calculateTotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.qty, 0);
}

const total = computed(function () {
  return cart().reduce(function (sum, item) {
    return sum + item.price * item.qty;
  }, 0);
});

app.get('/api/products', async (req, res) => {
  const products = await db.collection('articles').find().toArray();
  res.json(products);
});

app.post('/signin', async function (req, res) {
  const token = jwt.sign({ username: username }, secret, { expiresIn: '1h' });

  res.cookie('jwt', token, {
    httpOnly: true,
    sameSite: 'strict',
    secure: true,
  });

  res.json({ ok: true });
});

function auth(req, res, next) {
  const token = req.cookies.jwt;

  if (!token) {
    return res.sendStatus(401);
  }

  try {
    req.user = jwt.verify(token, secret);
    next();
  } catch (error) {
    res.sendStatus(403);
  }
}

export const routes: Routes = [
  { path: '', component: SearchComponent },
  { path: 'cart', component: CartComponent },
];

const app = express();
app.use(express.static(join(distFolder), { index: false }));
app.get('*', (req, res) => {
  res.sendFile(join(distFolder, 'index.html'));
});

